/*
 * meatrider_ptx_loader.c — run src/meatrider/meatrider.ptx on a real NVIDIA GPU.
 *
 * The tier's PTX kernel is generated by tools/gen_meatrider_ptx.py and until now
 * was only ever executed by the Python simulator (src/meatrider/test_meatrider_ptx.py).
 * This is the other half: load the PTX through the CUDA driver (which JITs it,
 * so no ptxas and no nvcc are needed), launch it, and hand the hit back.
 *
 *   int  anubis_meatrider_ptx_available(void);
 *   const char *anubis_meatrider_ptx_info(void);      "CUDA: Tesla T4 (PTX)"
 *   int  anubis_meatrider_ptx_solve(mid[8], tail[3], difficulty,
 *                                   start, count, budget_ms,
 *                                   &nonce, hashes[8], &dispatches);
 *      -> 0 hit, 1 range or budget exhausted, -1 failure
 *
 * The kernel's parameters are flat scalars plus one results pointer (see the
 * header of meatrider.ptx), and `hashes` is the display-order digest as eight
 * big-endian words, so printing them as %08x is the digest string.
 *
 * Build (driver API only, no toolkit headers, no -lcuda):
 *     cc -O2 -shared -fPIC -o libmeatrider_ptx_loader.so \
 *        src/meatrider/meatrider_ptx_loader.c -ldl
 *
 * Environment:
 *   ANUBIS_MEATRIDER_PTX    path to meatrider.ptx (default: meatrider.ptx,
 *                           then src/meatrider/meatrider.ptx)
 *   ANUBIS_PTX_CHUNK        nonces per launch (default 1<<22)
 *   ANUBIS_PTX_BLOCK        threads per block (default 256, clamp 32..1024)
 *
 * Every hit is re-derived by the C reference before it is believed, so a wrong
 * kernel costs a dispatch rather than a wrong answer -- this loader is a
 * benchmark and an experiment, not the library's dispatch path (that is
 * src/meatrider/meatrider_cuda.cu).
 */

#define _POSIX_C_SOURCE 199309L

#include <dlfcn.h>
#include <pthread.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef int CUresult;
typedef int CUdevice;
typedef unsigned long long CUdeviceptr;
typedef struct CUctx_st *CUcontext;
typedef struct CUmod_st *CUmodule;
typedef struct CUfunc_st *CUfunction;

static CUresult (*p_cuInit)(unsigned int);
static CUresult (*p_cuDeviceGetCount)(int *);
static CUresult (*p_cuDeviceGet)(CUdevice *, int);
static CUresult (*p_cuDeviceGetName)(char *, int, CUdevice);
static CUresult (*p_cuDevicePrimaryCtxRetain)(CUcontext *, CUdevice);
static CUresult (*p_cuCtxSetCurrent)(CUcontext);
static CUresult (*p_cuCtxSynchronize)(void);
static CUresult (*p_cuMemAlloc_v2)(CUdeviceptr *, size_t);
static CUresult (*p_cuMemFree_v2)(CUdeviceptr);
static CUresult (*p_cuMemcpyDtoH_v2)(void *, CUdeviceptr, size_t);
static CUresult (*p_cuMemcpyHtoD_v2)(CUdeviceptr, const void *, size_t);
static CUresult (*p_cuMemsetD8_v2)(CUdeviceptr, unsigned char, size_t);
static CUresult (*p_cuModuleLoadData)(CUmodule *, const void *);
static CUresult (*p_cuModuleGetFunction)(CUfunction *, CUmodule, const char *);
static CUresult (*p_cuLaunchKernel)(CUfunction, unsigned int, unsigned int,
                                    unsigned int, unsigned int, unsigned int,
                                    unsigned int, unsigned int, void *,
                                    void **, void **);

typedef struct {
    uint32_t count;
    uint32_t pad[3];
    uint32_t nonces[8];
    uint32_t hashes[8][8];
} mr_results;

#define MR_MAX_DEV 4

/* One of these per visible device: a context, its own JITed module (the driver
 * compiles the PTX per context), a results buffer and a host mirror. */
typedef struct {
    CUdevice dev;
    CUcontext ctx;
    CUmodule mod;
    CUfunction fn;
    CUdeviceptr d_results;
    mr_results h_results;
} mr_dev;

static struct {
    int state;              /* 0 untouched, 1 ready, -1 unavailable */
    int ndev;
    char info[160];
    mr_dev dev[MR_MAX_DEV];
} g_mr;

static double now_s(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec * 1e-9;
}

static int load_libcuda(void) {
    static const char *const cands[] = {
        "libcuda.so.1",
        "libcuda.so",
        "/usr/lib/x86_64-linux-gnu/libcuda.so.1",
        "/usr/local/nvidia/lib64/libcuda.so.1",
        "/usr/lib64/libcuda.so.1",
    };
    static const struct {
        const char *name;
        void **slot;
    } syms[] = {
        {"cuInit", (void **)(void *)&p_cuInit},
        {"cuDeviceGetCount", (void **)(void *)&p_cuDeviceGetCount},
        {"cuDeviceGet", (void **)(void *)&p_cuDeviceGet},
        {"cuDeviceGetName", (void **)(void *)&p_cuDeviceGetName},
        {"cuDevicePrimaryCtxRetain", (void **)(void *)&p_cuDevicePrimaryCtxRetain},
        {"cuCtxSetCurrent", (void **)(void *)&p_cuCtxSetCurrent},
        {"cuCtxSynchronize", (void **)(void *)&p_cuCtxSynchronize},
        {"cuMemAlloc_v2", (void **)(void *)&p_cuMemAlloc_v2},
        {"cuMemFree_v2", (void **)(void *)&p_cuMemFree_v2},
        {"cuMemcpyDtoH_v2", (void **)(void *)&p_cuMemcpyDtoH_v2},
        {"cuMemcpyHtoD_v2", (void **)(void *)&p_cuMemcpyHtoD_v2},
        {"cuMemsetD8_v2", (void **)(void *)&p_cuMemsetD8_v2},
        {"cuModuleLoadData", (void **)(void *)&p_cuModuleLoadData},
        {"cuModuleGetFunction", (void **)(void *)&p_cuModuleGetFunction},
        {"cuLaunchKernel", (void **)(void *)&p_cuLaunchKernel},
    };
    size_t i, j;

    if (p_cuInit != NULL) {
        return 0;
    }
    for (i = 0; i < sizeof cands / sizeof cands[0]; i++) {
        void *h = dlopen(cands[i], RTLD_NOW | RTLD_GLOBAL);
        int ok = 1;
        if (h == NULL) {
            continue;
        }
        for (j = 0; j < sizeof syms / sizeof syms[0]; j++) {
            *syms[j].slot = dlsym(h, syms[j].name);
            if (*syms[j].slot == NULL) {
                ok = 0;
            }
        }
        if (ok) {
            return 0;
        }
        dlclose(h);
        for (j = 0; j < sizeof syms / sizeof syms[0]; j++) {
            *syms[j].slot = NULL;
        }
    }
    return -1;
}

static char *read_text(const char *path, long *len_out) {
    FILE *f = fopen(path, "rb");
    long len;
    char *buf;

    if (f == NULL) {
        return NULL;
    }
    if (fseek(f, 0, SEEK_END) != 0 || (len = ftell(f)) <= 0 ||
        fseek(f, 0, SEEK_SET) != 0) {
        fclose(f);
        return NULL;
    }
    buf = (char *)malloc((size_t)len + 1);
    if (buf == NULL || fread(buf, 1, (size_t)len, f) != (size_t)len) {
        free(buf);
        fclose(f);
        return NULL;
    }
    buf[len] = '\0';
    fclose(f);
    *len_out = len;
    return buf;
}

static int mr_init(void) {
    const char *env, *path;
    char name[128];
    char *ptx;
    long len = 0;
    CUresult err;
    int i, n = 0;

    if (g_mr.state != 0) {
        return g_mr.state == 1;
    }
    g_mr.state = -1;
    if (load_libcuda() != 0) {
        return 0;
    }
    if (p_cuInit(0) != 0) {
        return 0;
    }
    if (p_cuDeviceGetCount(&n) != 0 || n < 1) {
        return 0;
    }
    if (n > MR_MAX_DEV) {
        n = MR_MAX_DEV;
    }

    env = getenv("ANUBIS_MEATRIDER_PTX");
    path = (env != NULL && env[0] != '\0') ? env : "meatrider.ptx";
    ptx = read_text(path, &len);
    if (ptx == NULL) {
        path = "src/meatrider/meatrider.ptx";
        ptx = read_text(path, &len);
    }
    if (ptx == NULL) {
        fprintf(stderr, "meatrider_ptx: cannot read the PTX (set ANUBIS_MEATRIDER_PTX)\n");
        return 0;
    }

    for (i = 0; i < n; i++) {
        mr_dev *d = &g_mr.dev[i];

        if (p_cuDeviceGet(&d->dev, i) != 0 ||
            p_cuDevicePrimaryCtxRetain(&d->ctx, d->dev) != 0 ||
            p_cuCtxSetCurrent(d->ctx) != 0) {
            return 0;
        }
        err = p_cuModuleLoadData(&d->mod, ptx);
        if (err != 0) {
            fprintf(stderr, "meatrider_ptx: device %d: cuModuleLoadData failed: %d\n",
                    i, (int)err);
            free(ptx);
            return 0;
        }
        if (p_cuModuleGetFunction(&d->fn, d->mod, "meatrider_kernel") != 0) {
            fprintf(stderr, "meatrider_ptx: device %d: no meatrider_kernel entry\n", i);
            free(ptx);
            return 0;
        }
        if (p_cuMemAlloc_v2(&d->d_results, sizeof d->h_results) != 0) {
            free(ptx);
            return 0;
        }
        memset(&d->h_results, 0, sizeof d->h_results);
        if (i == 0) {
            name[0] = '\0';
            if (p_cuDeviceGetName(name, (int)sizeof name, d->dev) != 0) {
                name[0] = '\0';
            }
        }
    }
    free(ptx);
    if (p_cuCtxSetCurrent(g_mr.dev[0].ctx) != 0) {
        return 0;
    }
    g_mr.ndev = n;
    if (n == 1) {
        snprintf(g_mr.info, sizeof g_mr.info, "CUDA: %.80s (PTX)", name);
    } else {
        snprintf(g_mr.info, sizeof g_mr.info, "CUDA: %.64s x%d (PTX)", name, n);
    }
    g_mr.state = 1;
    return 1;
}

int anubis_meatrider_ptx_available(void) {
    return mr_init();
}

const char *anubis_meatrider_ptx_info(void) {
    return mr_init() ? g_mr.info : NULL;
}

static uint32_t env_u32(const char *name, uint32_t fallback) {
    const char *s = getenv(name);
    if (s == NULL || s[0] == '\0') {
        return fallback;
    }
    return (uint32_t)strtoul(s, NULL, 0);
}

typedef struct {
    int i;                  /* device index */
    const uint32_t *mid;
    const uint32_t *tail;
    int difficulty;
    uint32_t start;
    uint32_t end;
    uint32_t chunk;
    uint32_t block;
    double deadline;        /* monotonic seconds, 0 = none */
    volatile int *stop;
    int rc;                 /* 0 hit, 1 exhausted, -1 failure */
    uint32_t nonce;
    uint32_t hashes[8];
    int dispatches;
} mr_job;

static int mr_launch(mr_dev *d, const uint32_t mid[8], const uint32_t tail[3],
                     int difficulty, uint32_t base, uint32_t n, uint32_t block) {
    uint32_t grid = (n + block - 1u) / block;
    uint32_t difficulty_arg = (uint32_t)difficulty;
    uint32_t base_arg = base;
    uint32_t n_arg = n;
    CUdeviceptr res = d->d_results;
    void *args[15];
    int i;

    for (i = 0; i < 8; i++) {
        args[i] = (void *)(void *)&mid[i];
    }
    for (i = 0; i < 3; i++) {
        args[8 + i] = (void *)(void *)&tail[i];
    }
    args[11] = (void *)&difficulty_arg;
    args[12] = (void *)&base_arg;
    args[13] = (void *)&n_arg;
    args[14] = (void *)&res;

    if (p_cuMemsetD8_v2(d->d_results, 0, sizeof d->h_results) != 0) {
        return -1;
    }
    if (p_cuLaunchKernel(d->fn, grid, 1, 1, block, 1, 1, 0, NULL, args, NULL) != 0) {
        return -1;
    }
    if (p_cuCtxSynchronize() != 0) {
        return -1;
    }
    if (p_cuMemcpyDtoH_v2(&d->h_results, d->d_results, sizeof d->h_results) != 0) {
        return -1;
    }
    return 0;
}

static void *mr_worker(void *argp) {
    mr_job *j = (mr_job *)argp;
    mr_dev *d = &g_mr.dev[j->i];
    uint64_t base = j->start;

    j->rc = 1;
    if (p_cuCtxSetCurrent(d->ctx) != 0) {
        j->rc = -1;
        return NULL;
    }
    while (base <= (uint64_t)j->end && !*j->stop) {
        uint64_t remaining = (uint64_t)j->end - base + 1u;
        uint32_t n = (uint32_t)(remaining < (uint64_t)j->chunk ? remaining
                                                              : (uint64_t)j->chunk);
        int i;

        if (n == 0) {
            break;
        }
        if (mr_launch(d, j->mid, j->tail, j->difficulty, (uint32_t)base, n,
                      j->block) != 0) {
            j->rc = -1;
            return NULL;
        }
        j->dispatches++;
        base += n;
        if (d->h_results.count > 0) {
            j->nonce = d->h_results.nonces[0];
            for (i = 0; i < 8; i++) {
                j->hashes[i] = d->h_results.hashes[0][i];
            }
            j->rc = 0;
            *j->stop = 1;
            return NULL;
        }
        if (j->deadline > 0.0 && now_s() > j->deadline) {
            j->rc = 1;
            return NULL;
        }
    }
    return NULL;
}

int anubis_meatrider_ptx_solve(const uint32_t mid[8], const uint32_t tail[3],
                               int difficulty, uint32_t start, uint32_t count,
                               double budget_ms, uint32_t *out_nonce,
                               uint32_t out_hashes[8], int *out_dispatches) {
    mr_job jobs[MR_MAX_DEV];
    pthread_t threads[MR_MAX_DEV];
    uint32_t chunk, block;
    uint64_t end, per;
    double deadline = 0.0;
    volatile int stop = 0;
    int i, spawned = 0, rc = 1;

    if (mid == NULL || tail == NULL || out_nonce == NULL) {
        return -1;
    }
    if (!mr_init()) {
        return -1;
    }
    chunk = env_u32("ANUBIS_PTX_CHUNK", 1u << 22);
    if (chunk < 1024u) {
        chunk = 1024u;
    }
    block = env_u32("ANUBIS_PTX_BLOCK", 256u);
    if (block < 32u) {
        block = 32u;
    }
    if (block > 1024u) {
        block = 1024u;
    }
    end = 0xffffffffull;
    if (count > 0) {
        uint64_t last = (uint64_t)start + (uint64_t)count - 1u;
        if (last < end) {
            end = last;
        }
    }
    if (budget_ms > 0.0) {
        deadline = now_s() + budget_ms / 1000.0;
    }

    per = (end - (uint64_t)start + 1u + (uint64_t)g_mr.ndev - 1u) /
          (uint64_t)g_mr.ndev;
    for (i = 0; i < g_mr.ndev; i++) {
        uint64_t lo = (uint64_t)start + (uint64_t)i * per;
        uint64_t hi = lo + per - 1u;

        if (lo > end) {
            break;
        }
        jobs[i].i = i;
        jobs[i].mid = mid;
        jobs[i].tail = tail;
        jobs[i].difficulty = difficulty;
        jobs[i].start = (uint32_t)lo;
        jobs[i].end = (uint32_t)(hi > end ? end : hi);
        jobs[i].chunk = chunk;
        jobs[i].block = block;
        jobs[i].deadline = deadline;
        jobs[i].stop = &stop;
        jobs[i].rc = 1;
        jobs[i].nonce = 0;
        jobs[i].dispatches = 0;
        if (pthread_create(&threads[i], NULL, mr_worker, &jobs[i]) != 0) {
            jobs[i].rc = -1;
            break;
        }
        spawned++;
    }
    for (i = 0; i < spawned; i++) {
        pthread_join(threads[i], NULL);
    }
    for (i = 0; i < spawned; i++) {
        if (jobs[i].rc == 0) {
            int k;
            *out_nonce = jobs[i].nonce;
            if (out_hashes != NULL) {
                for (k = 0; k < 8; k++) {
                    out_hashes[k] = jobs[i].hashes[k];
                }
            }
            if (out_dispatches != NULL) {
                *out_dispatches = jobs[i].dispatches;
            }
            return 0;
        }
        if (jobs[i].rc < 0) {
            rc = -1;
        }
    }
    if (out_dispatches != NULL) {
        *out_dispatches = spawned > 0 ? jobs[0].dispatches : 0;
    }
    if (spawned == 0) {
        return -1;
    }
    return rc;
}
